 1	import Foundation
 2	
 3	/// The bounded, ordered event log of one conversation subscription. Sequence numbers are
 4	/// monotonic for the life of the log, including across `clear()`, so a client's `since`
 5	/// never means two different things. Retention is by event count and estimated bytes.
 6	nonisolated struct MirrorConversationLog: Sendable {
 7	  struct Snapshot: Equatable, Sendable {
 8	    let events: [MirrorConversationEvent]
 9	    /// Events between the requested point and `events.first` were dropped.
10	    let gap: Bool
11	    let latestSequence: UInt64
12	  }
13	
14	  var maximumEvents = 500
15	  var maximumBytes = 1_024 * 1_024
16	
17	  private(set) var events: [MirrorConversationEvent] = []
18	  private(set) var latestSequence: UInt64 = 0
19	  private var retainedBytes = 0
20	  /// The sequence the current segment started after; `clear()` moves it.
21	  private var segmentStart: UInt64 = 0
22	
23	  @discardableResult
24	  mutating func append(_ event: MirrorConversationEvent) -> MirrorConversationEvent {
25	    var assigned = event
26	    latestSequence += 1
27	    assigned.sequence = latestSequence
28	    events.append(assigned)
29	    retainedBytes += assigned.estimatedBytes
30	    evictIfNeeded()
31	    return assigned
32	  }
33	
34	  @discardableResult
35	  mutating func append(contentsOf newEvents: [MirrorConversationEvent]) -> [MirrorConversationEvent] {
36	    newEvents.map { append($0) }
37	  }
38	
39	  /// Drops retained events; sequences keep counting.
40	  mutating func clear() {
41	    events.removeAll()
42	    retainedBytes = 0
43	    segmentStart = latestSequence
44	  }
45	
46	  func snapshot(since: UInt64?) -> Snapshot {
47	    guard let oldest = events.first?.sequence else {
48	      return Snapshot(events: [], gap: false, latestSequence: latestSequence)
49	    }
50	    guard let since else {
51	      return Snapshot(events: events, gap: oldest > segmentStart + 1, latestSequence: latestSequence)
52	    }
53	    if since >= latestSequence { return Snapshot(events: [], gap: false, latestSequence: latestSequence) }
54	    if since + 1 < oldest { return Snapshot(events: events, gap: true, latestSequence: latestSequence) }
55	    return Snapshot(events: events.filter { $0.sequence > since }, gap: false, latestSequence: latestSequence)
56	  }
57	
58	  private mutating func evictIfNeeded() {
59	    while events.count > 1, events.count > maximumEvents || retainedBytes > maximumBytes {
60	      retainedBytes -= events.removeFirst().estimatedBytes
61	    }
62	  }
63	}
64	
65	extension MirrorConversationEvent {
66	  /// A cheap size estimate for retention: the texts an event carries plus a fixed envelope.
67	  nonisolated var estimatedBytes: Int {
