 1	import Foundation
 2	
 3	/// Splits appended bytes into complete JSONL lines. A partial last line waits for more
 4	/// bytes; a line over `maximumLineBytes` is dropped whole and counted.
 5	nonisolated struct MirrorJSONLineReader: Sendable {
 6	  var maximumLineBytes = 8 * 1024 * 1024
 7	  private(set) var droppedLines = 0
 8	  private var buffer = Data()
 9	  private var skippingOversizedLine = false
10	
11	  mutating func append(_ data: Data) -> [Data] {
12	    buffer.append(data)
13	    var lines: [Data] = []
14	    while let newline = buffer.firstIndex(of: 0x0A) {
15	      var line = buffer.subdata(in: buffer.startIndex..<newline)
16	      buffer.removeSubrange(buffer.startIndex...newline)
17	      if skippingOversizedLine {
18	        skippingOversizedLine = false
19	        continue
20	      }
21	      if line.last == 0x0D { line.removeLast() }
22	      if line.count > maximumLineBytes {
23	        droppedLines += 1
24	      } else if !line.isEmpty {
25	        lines.append(line)
26	      }
27	    }
28	    if buffer.count > maximumLineBytes {
29	      buffer.removeAll()
30	      skippingOversizedLine = true
31	      droppedLines += 1
32	    }
33	    return lines
34	  }
35	
36	  /// Drops the bytes before the first newline: the tail of a file read from a middle offset.
37	  mutating func discardPartialFirstLine() {
38	    skippingOversizedLine = true
39	  }
40	
41	  mutating func reset() {
42	    buffer.removeAll()
43	    skippingOversizedLine = false
44	  }
45	}
46	
