 3	/// Decodes tail changes into events on the tail's queue: bytes → lines → records → adapter.
 4	nonisolated final class MirrorTranscriptPipeline: @unchecked Sendable {
 5	  private let agent: DetectedAgent
 6	  private var reader = MirrorJSONLineReader()
 7	  private var adapter: any MirrorConversationAdapter
 8	  private(set) var rejectedRecords = 0
 9	
10	  init?(agent: DetectedAgent) {
11	    guard let adapter = MirrorConversationAdapters.make(for: agent) else { return nil }
12	    self.agent = agent
13	    self.adapter = adapter
14	  }
15	
16	  func ingest(_ change: MirrorTranscriptTail.Change) -> [MirrorConversationEvent] {
17	    switch change {
18	    case .replay(let data, let startsMidRecord):
19	      restart()
20	      if startsMidRecord { reader.discardPartialFirstLine() }
21	      return decode(reader.append(data))
22	    case .appended(let data):
23	      return decode(reader.append(data))
24	    case .rotated:
25	      restart()
26	      return [.init(.sessionChanged, .session(.init(reason: .rotated)), at: Date(), source: .host)]
27	    case .missing:
28	      return [.init(.sessionPending, .session(.init(reason: .uncertain)), at: Date(), source: .host)]
29	    }
30	  }
31	
32	  private func restart() {
33	    reader.reset()
34	    if let fresh = MirrorConversationAdapters.make(for: agent) { adapter = fresh }
35	  }
36	
37	  private func decode(_ lines: [Data]) -> [MirrorConversationEvent] {
38	    var events: [MirrorConversationEvent] = []
39	    for line in lines {
40	      guard let record = try? JSONSerialization.jsonObject(with: line) as? MirrorConversationRecord else {
41	        rejectedRecords += 1
42	        continue
43	      }
44	      events += adapter.events(for: record)
45	    }
46	    return events
47	  }
48	}
