 6	struct MirrorConversationStatusMapperTests {
 7	  @Test func emitsOnlyChangesWithKindAndSource() {
 8	    var mapper = MirrorConversationStatusMapper()
 9	    var pane = PaneAgentState(detectedAgent: .claude, state: .working)
10	    pane.decision = .init(state: .working, reason: .programStatus(.working))
11	    let working = mapper.event(for: pane, at: Date())
12	    #expect(working?.kind == .agentStatus && working?.source == .osc)
13	    #expect(mapper.event(for: pane, at: Date()) == nil)
14	    pane.state = .blocked
15	    pane.decision = .init(state: .blocked, reason: .programStatus(.blocked(.permission)))
16	    guard case .status(let blocked) = mapper.event(for: pane, at: Date())?.payload else {
17	      Issue.record("expected a status event")
18	      return
19	    }
20	    #expect(blocked.state == .blocked && blocked.kind == "permission" && blocked.reason == "osc.blocked.permission")
21	    pane.decision = .init(state: .blocked, reason: .screen(.noRuleMatched))
22	    guard let screen = mapper.event(for: pane, at: Date()), case .status(let fromScreen) = screen.payload else {
23	      Issue.record("expected a status event")
24	      return
25	    }
26	    #expect(screen.source == .screen && fromScreen.kind == "unspecified")
27	    #expect(mapper.event(for: PaneAgentState(state: .working), at: Date()) == nil)
28	  }
29	}
